const fs = require("node:fs");
const path = require("node:path");

const PUBLIC_STATE = Object.freeze({
  schemaVersion: 1,
  revision: 1,
  updatedAt: "2026-01-01T00:00:00.000Z",
  updatedBy: "public-test",
  source: "synthetic fixture",
  status: "active",
  objective: "verify public fixture isolation",
  summary: "public synthetic state",
  completed: ["fixture created"],
  nextActions: ["run isolated verification"],
  blockers: [],
  decisions: ["use synthetic inputs only"],
  workingFiles: ["tests/fixtures/public-fixtures.cjs"],
  verification: ["clean clone fixture"],
});

const PUBLIC_MEMORY = [
  "# Public synthetic profile",
  "",
  "- This profile is generated by a repository test.",
  "- It contains no user or machine-specific information.",
  "",
].join("\n");

const PUBLIC_CONTEXT = [
  "# Public synthetic context",
  "",
  "This file exists only to make recovery-source checks self-contained.",
  "",
].join("\n");

const PUBLIC_CORE = Object.freeze({
  "core/rules.md": "# Public synthetic rules\n\nUse only repository-owned test inputs.\n",
  "core/reply-style.md": "# Public synthetic reply style\n\nKeep test output concise.\n",
});

function ensureParent(file) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
}

function writeJson(file, value) {
  ensureParent(file);
  fs.writeFileSync(file, JSON.stringify(value, null, 2) + "\n", "utf8");
}

function writePublicState(root, overrides = {}) {
  writeJson(path.join(root, "current-state.json"), { ...PUBLIC_STATE, ...overrides });
}

function writePublicMemory(root, text = PUBLIC_MEMORY) {
  const file = path.join(root, "MEMORY.md");
  ensureParent(file);
  fs.writeFileSync(file, text, "utf8");
}

function writePublicContext(root, text = PUBLIC_CONTEXT) {
  const file = path.join(root, ".context", "CONTEXT.md");
  ensureParent(file);
  fs.writeFileSync(file, text, "utf8");
}

function writePublicCore(root) {
  for (const [relative, text] of Object.entries(PUBLIC_CORE)) {
    const file = path.join(root, relative);
    ensureParent(file);
    fs.writeFileSync(file, text, "utf8");
  }
}

function writePublicDaily(root, name = "2099-01-01.md", marker = "PUBLIC_SYNTHETIC_DAILY_RAW") {
  const file = path.join(root, "daily", name);
  ensureParent(file);
  fs.writeFileSync(file, `# ${name.slice(0, 10)}\n\n- synthetic test record: ${marker}\n`, "utf8");
}

module.exports = {
  PUBLIC_STATE,
  writePublicState,
  writePublicMemory,
  writePublicContext,
  writePublicCore,
  writePublicDaily,
};
